from ..section_generic import TextBasedSectionGeneric


class SectionMain(TextBasedSectionGeneric):
    def __init__(self, subsection_separator='\n'):
        super().__init__(subsection_separator)

    def _prepare_section_content(self, ue_config, *args, **kwargs):
        db_head = (
            "UEID", "IMSI", "IMEISV", "IPVER",
            "PMI", "RI", "CQI", "UECAT", "INTEGRTALG",
            "CRYPTALG", "AUTN", "CK-IK", "RAND", "XRES",
            "OLD_GUTI", "REATTACH_MODE", "UE_CAPABILITIES", "UE_POOL"
        )
        lmts_to_yaml_map = {
            'UE_POOL': 'pool',
            'CRYPTALG': 'eea',
            'INTEGRTALG': 'eia',
            'UECAT': 'cat'
        }

        header_line = ';'.join(db_head)
        self._section_content = [[header_line]]

        for h_ue in ue_config['ue'].values():
            line = ''
            for i, header in enumerate(db_head):
                if header in lmts_to_yaml_map:
                    line += str(h_ue.get(lmts_to_yaml_map[header], ''))
                else:
                    line += str(h_ue.get(header.lower(), ''))

                if i < len(db_head) - 1:
                    line += ','
            self._section_content[0].append(line)
        self._section_content[0][-1] += '\n'
